"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"

export default function AnalyticsPage() {
  const [data, setData] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetchAnalytics()
  }, [])

  const fetchAnalytics = async () => {
    try {
      const res = await fetchApi(`/api/analytics`)
      const result = await res.json()
      setData(result)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  if (loading) return <div className="p-8 text-[#bfa8a2] font-mono">CALCULATING METRICS...</div>
  if (!data) return <div className="p-8 text-[#ac120c] font-mono">ERROR FETCHING DATA</div>

  const totalSelectionsAndRejections = (data.selectedVsRejected?.SELECTED || 0) + (data.selectedVsRejected?.REJECTED || 0)
  const maxInterviews = data.interviewsByDay ? Math.max(...data.interviewsByDay.map((d: any) => d.count), 1) : 1

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <header className="flex items-end justify-between">
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
            <DiamondIcon />
            <span>System Telemetry</span>
          </div>
          <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
            Global Analytics
          </h1>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card className="p-8">
          <h2 className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-[0.06em] mb-6">Application Funnel</h2>
          <div className="flex flex-col gap-4">
            {Object.entries(data.applicationsByStatus).map(([status, count]) => {
              const max = data.metrics.totalApplications || 1
              const percentage = ((count as number) / max) * 100
              return (
                <div key={status} className="flex flex-col gap-1">
                  <div className="flex justify-between font-mono text-[11px] text-[#f4ede4]">
                    <span>{status}</span>
                    <span>{count as number}</span>
                  </div>
                  <div className="w-full bg-[#120202] h-2 rounded-full overflow-hidden border border-[#2a0d0d]">
                    <div 
                      className="bg-[#ac120c] h-full transition-all duration-1000" 
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                </div>
              )
            })}
          </div>
        </Card>

        <Card className="p-8">
          <h2 className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-[0.06em] mb-6">Department Distribution</h2>
          <div className="flex flex-col gap-4">
            {data.applicationsByDepartment.map((dept: any) => {
              const max = data.metrics.totalCandidates || 1
              const percentage = (dept.count / max) * 100
              return (
                <div key={dept.department} className="flex flex-col gap-1">
                  <div className="flex justify-between font-mono text-[11px] text-[#f4ede4]">
                    <span>{dept.department}</span>
                    <span>{dept.count}</span>
                  </div>
                  <div className="w-full bg-[#120202] h-2 rounded-full overflow-hidden border border-[#2a0d0d]">
                    <div 
                      className="bg-[#d07d22] h-full transition-all duration-1000" 
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                </div>
              )
            })}
          </div>
        </Card>

        <Card className="p-8">
          <h2 className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-[0.06em] mb-6">Selected vs Rejected Ratio</h2>
          <div className="flex flex-col gap-4">
            {["SELECTED", "REJECTED"].map((decision) => {
              const count = data.selectedVsRejected?.[decision] || 0
              const percentage = totalSelectionsAndRejections > 0 ? (count / totalSelectionsAndRejections) * 100 : 0
              return (
                <div key={decision} className="flex flex-col gap-1">
                  <div className="flex justify-between font-mono text-[11px] text-[#f4ede4]">
                    <span>{decision}</span>
                    <span>{count}</span>
                  </div>
                  <div className="w-full bg-[#120202] h-2 rounded-full overflow-hidden border border-[#2a0d0d]">
                    <div 
                      className={`${decision === 'SELECTED' ? 'bg-[#2e7d32]' : 'bg-[#ac120c]'} h-full transition-all duration-1000`} 
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                </div>
              )
            })}
          </div>
        </Card>

        <Card className="p-8">
          <h2 className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-[0.06em] mb-6">Interviews by Day</h2>
          <div className="flex flex-col justify-end h-[150px] gap-2 border-l border-b border-[#2a0d0d] p-4">
            <div className="flex items-end gap-2 h-full">
              {data.interviewsByDay?.length === 0 ? (
                 <span className="font-mono text-[10px] text-[#bfa8a2]">No data</span>
              ) : (
                data.interviewsByDay?.map((day: any) => {
                  const heightPercentage = (day.count / maxInterviews) * 100
                  return (
                    <div key={day.date} className="relative flex flex-col justify-end items-center group h-full flex-1">
                      <div className="w-full bg-[#ac120c]/80 hover:bg-[#ac120c] transition-all" style={{ height: `${heightPercentage}%`, minHeight: '4px' }} />
                      <div className="absolute -bottom-6 font-mono text-[8px] text-[#bfa8a2] whitespace-nowrap overflow-hidden text-ellipsis w-full text-center">
                        {new Date(day.date).toLocaleDateString('en-US', { timeZone: 'Asia/Kolkata',  month: 'short', day: 'numeric'})}
                      </div>
                      <div className="absolute -top-6 opacity-0 group-hover:opacity-100 transition-opacity font-mono text-[10px] text-[#f4ede4]">
                        {day.count}
                      </div>
                    </div>
                  )
                })
              )}
            </div>
          </div>
        </Card>

      </div>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"

import React, { useState, useEffect } from "react"
import { Card } from "@/components/ui/Card"
import { DiamondIcon, SearchIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"

export default function AdminApplicationsPage() {
  const [applications, setApplications] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  
  // Filters & Pagination
  const [search, setSearch] = useState("")
  const [status, setStatus] = useState("")
  const [department, setDepartment] = useState("")
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  
  const [debouncedSearch, setDebouncedSearch] = useState("")

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 500)
    return () => clearTimeout(timer)
  }, [search])

  useEffect(() => {
    fetchApplications()
  }, [debouncedSearch, status, department, page])

  const fetchApplications = async () => {
    setLoading(true)
    try {
      const query = new URLSearchParams({
        page: page.toString(),
        limit: "10",
        search: debouncedSearch,
        status,
        department
      })
      const res = await fetchApi(`/api/applications?${query.toString()}`)
      const data = await res.json()
      setApplications(data.items || [])
      setTotalPages(data.totalPages || 1)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString("en-US", { timeZone: "Asia/Kolkata", 
      month: "short", day: "numeric", year: "numeric"
    })
  }

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out] pb-10">
      <header className="flex flex-col gap-2">
        <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
          <DiamondIcon />
          <span>Global Data View</span>
        </div>
        <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
          Applications Master
        </h1>
      </header>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-4 bg-[#120202] p-4 rounded-xl border border-[#2a0d0d]">
        <div className="flex-1 relative">
          <input 
            type="text" 
            placeholder="Search candidate name..." 
            className="w-full bg-[#1a0606] border border-[#2a0d0d] rounded-lg px-4 py-2.5 text-[#f4ede4] font-mono text-[12px] focus:outline-none focus:border-[#ac120c]"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
          />
        </div>
        <div className="flex flex-col sm:flex-row gap-4">
          <select 
            className="bg-[#1a0606] border border-[#2a0d0d] rounded-lg px-4 py-2.5 text-[#f4ede4] font-mono text-[12px] focus:outline-none focus:border-[#ac120c]"
            value={status}
            onChange={(e) => { setStatus(e.target.value); setPage(1); }}
          >
            <option value="">All Statuses</option>
            <option value="APPLIED">Applied</option>
            <option value="UNDER_REVIEW">Under Review</option>
            <option value="SHORTLISTED">Shortlisted</option>
            <option value="INTERVIEW_SCHEDULED">Interview Scheduled</option>
            <option value="INTERVIEW_COMPLETED">Interview Completed</option>
            <option value="WAITLISTED">Waitlisted</option>
            <option value="SELECTED">Selected</option>
            <option value="REJECTED">Rejected</option>
          </select>

          <select 
            className="bg-[#1a0606] border border-[#2a0d0d] rounded-lg px-4 py-2.5 text-[#f4ede4] font-mono text-[12px] focus:outline-none focus:border-[#ac120c]"
            value={department}
            onChange={(e) => { setDepartment(e.target.value); setPage(1); }}
          >
            <option value="">All Departments</option>
            <option value="Web Development">Web Development</option>
            <option value="AI/ML">AI/ML</option>
            <option value="App Development">App Development</option>
            <option value="Design">Design</option>
            <option value="Events">Events</option>
            <option value="Operations">Operations</option>
            <option value="Competitive Programming">Competitive Programming</option>
            <option value="Cybersecurity">Cybersecurity</option>
          </select>
        </div>
      </div>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[800px]">
            <thead>
              <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">CANDIDATE NAME</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">EMAIL</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">DEPT</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">APP DATE</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">APP STATUS</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em] text-right">ACTIONS</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#2a0d0d]">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-[#bfa8a2] font-mono">LOADING DATA...</td></tr>
              ) : applications.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-[#bfa8a2] font-mono">NO APPLICATIONS FOUND.</td></tr>
              ) : (
                applications.map((app) => {
                  const c = app.candidate
                  return (
                    <tr key={app.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                      <td className="p-4 text-[#f4ede4] font-medium">{c?.name || "Unknown"}</td>
                      <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">{c?.email || "-"}</td>
                      <td className="p-4 text-[#bfa8a2]">{c?.department || "-"}</td>
                      <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">
                        {app.submitted_at ? formatDate(app.submitted_at) : "-"}
                      </td>
                      <td className="p-4">
                        <StatusPill status={app.status.toLowerCase().includes('reject') ? 'rejected' : 'pending'}>
                          {app.status || "APPLIED"}
                        </StatusPill>
                      </td>
                      <td className="p-4 text-right">
                        <a href={`/admin/candidates/${c?.id}`} className="text-[#d07d22] font-mono text-[10px] uppercase hover:underline">
                          VIEW PROFILE
                        </a>
                      </td>
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        </div>
      </Card>
      
      {/* Pagination */}
      {!loading && totalPages > 1 && (
        <div className="flex justify-between items-center bg-[#120202] p-4 rounded-xl border border-[#2a0d0d]">
          <Button 
            variant="ghost" 
            onClick={() => setPage(p => Math.max(1, p - 1))}
            disabled={page === 1}
          >
            PREV
          </Button>
          <span className="font-mono text-[#bfa8a2] text-[12px]">
            PAGE {page} OF {totalPages}
          </span>
          <Button 
            variant="ghost" 
            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
          >
            NEXT
          </Button>
        </div>
      )}
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"

export default function AuditLogsPage() {
  const [logs, setLogs] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetchLogs()
  }, [])

  const fetchLogs = async () => {
    try {
      const res = await fetchApi(`/api/audit-logs`)
      const data = await res.json()
      setLogs(data.logs || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString("en-US", { timeZone: "Asia/Kolkata", 
      month: "short", day: "numeric", hour: "2-digit", minute: "2-digit", second: "2-digit"
    })
  }

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <header className="flex flex-col gap-2">
        <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
          <DiamondIcon />
          <span>Security & Operations</span>
        </div>
        <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
          System Audit Logs
        </h1>
      </header>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">TIMESTAMP</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">ACTOR</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">ACTION</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">ENTITY</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#2a0d0d]">
              {loading ? (
                <tr><td colSpan={4} className="p-8 text-center text-[#bfa8a2] font-mono">RETRIEVING LOGS...</td></tr>
              ) : logs.length === 0 ? (
                <tr><td colSpan={4} className="p-8 text-center text-[#bfa8a2] font-mono">NO LOGS FOUND.</td></tr>
              ) : (
                logs.map(log => (
                  <tr key={log.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                    <td className="p-4 text-[#bfa8a2] font-mono text-[11px] whitespace-nowrap">
                      {formatDate(log.timestamp)}
                    </td>
                    <td className="p-4">
                      {log.user ? (
                        <>
                          <p className="text-[#f4ede4] font-medium text-sm">{log.user.name}</p>
                          <p className="text-[#bfa8a2] font-mono text-[10px]">{log.user.role}</p>
                        </>
                      ) : (
                        <p className="text-[#d07d22] font-mono text-[11px]">SYSTEM</p>
                      )}
                    </td>
                    <td className="p-4 text-[#f4ede4] font-mono text-[12px]">{log.action}</td>
                    <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">
                      {log.entity} {log.entity_id ? `(#${log.entity_id})` : ""}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { useParams, useRouter } from "next/navigation"
import { Card } from "@/components/ui/Card"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"

export default function AdminCandidateProfile() {
  const { id } = useParams()
  const router = useRouter()
  const [candidate, setCandidate] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [actionLoading, setActionLoading] = useState(false)
  const [error, setError] = useState("")

  useEffect(() => {
    fetchCandidate()
  }, [id])

  const fetchCandidate = async () => {
    try {
      const res = await fetchApi(`/api/candidates/${id}`)
      if (!res.ok) throw new Error("Failed to fetch")
      const data = await res.json()
      setCandidate(data.candidate)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const updateApplicationStatus = async (appId: number, status: string) => {
    if (!confirm(`Are you sure you want to mark this application as ${status}?`)) return;
    
    setActionLoading(true)
    setError("")
    try {
      const res = await fetchApi(`/api/applications/${appId}`, {  
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status })
      })
      if (!res.ok) {
        const d = await res.json()
        throw new Error(d.error || "Failed to update status")
      }
      fetchCandidate()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setActionLoading(false)
    }
  }

  if (loading) return <div className="p-8 text-center text-[#bfa8a2] font-mono">LOADING PROFILE...</div>
  if (!candidate) return <div className="p-8 text-center text-[#bfa8a2] font-mono">CANDIDATE NOT FOUND.</div>

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <div className="flex justify-between items-center">
        <h1 className="font-display font-bold text-[32px] sm:text-[40px] text-[#f4ede4]">
          {candidate.name}
        </h1>
        <Button variant="ghost" onClick={() => router.back()}>BACK</Button>
      </div>

      {error && (
        <div className="bg-[#ac120c]/10 border border-[#ac120c]/50 text-[#ac120c] p-4 rounded-lg text-sm font-medium">
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card className="p-6">
          <h2 className="text-[#d07d22] font-mono text-[14px] uppercase mb-4">Contact Information</h2>
          <div className="flex flex-col gap-3 text-[#f4ede4]">
            <p><span className="text-[#bfa8a2] font-mono mr-2">EMAIL:</span> {candidate.email}</p>
            <p><span className="text-[#bfa8a2] font-mono mr-2">PHONE:</span> {candidate.phone}</p>
            <p><span className="text-[#bfa8a2] font-mono mr-2">REG NO:</span> {candidate.registration_number}</p>
            <p><span className="text-[#bfa8a2] font-mono mr-2">DEPT:</span> {candidate.department}</p>
            {candidate.resume_url && (
              <p>
                <span className="text-[#bfa8a2] font-mono mr-2">RESUME:</span>
                <a href={candidate.resume_url} target="_blank" rel="noreferrer" className="text-[#d07d22] underline">View Resume</a>
              </p>
            )}
          </div>
        </Card>

        <Card className="p-6">
          <h2 className="text-[#d07d22] font-mono text-[14px] uppercase mb-4">Applications</h2>
          <div className="flex flex-col gap-4">
            {candidate.applications?.map((app: any) => (
              <div key={app.id} className="bg-[#1a0606] p-4 rounded border border-[#2a0d0d]">
                <div className="flex justify-between items-center mb-2">
                  <span className="font-mono text-[#bfa8a2] text-[12px]">Application #{app.id}</span>
                  <StatusPill status={app.status.toLowerCase().includes('reject') ? 'rejected' : 'pending'}>
                    {app.status}
                  </StatusPill>
                </div>
                <div className="mt-4 flex flex-col gap-3">
                  {Object.entries(app.answers || {}).length > 0 ? (
                    Object.entries(app.answers).map(([questionId, answer]: [string, any]) => (
                      <div key={questionId} className="bg-[#2a0d0d]/30 p-3 rounded">
                        <div className="font-mono text-[10px] text-[#bfa8a2] mb-1">QUESTION ID: {questionId}</div>
                        <div className="font-body text-[14px] text-[#f4ede4] whitespace-pre-wrap">{String(answer)}</div>
                      </div>
                    ))
                  ) : (
                    <p className="text-[12px] text-[#bfa8a2]">No answers provided.</p>
                  )}
                </div>
                <div className="flex gap-2 flex-wrap border-t border-[#2a0d0d] pt-3 mt-4">
                  {(app.status === "APPLIED") && (
                    <>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "UNDER_REVIEW")} disabled={actionLoading} className="text-[#3498db] border border-[#3498db] hover:bg-[#3498db] hover:text-[#0a0202]">Mark Under Review</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "REJECTED")} disabled={actionLoading} className="text-[#ac120c] border border-[#ac120c] hover:bg-[#ac120c] hover:text-[#f4ede4]">Reject</Button>
                    </>
                  )}
                  {(app.status === "UNDER_REVIEW") && (
                    <>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "SHORTLISTED")} disabled={actionLoading} className="text-[#d07d22] border border-[#d07d22] hover:bg-[#d07d22] hover:text-[#0a0202]">Shortlist</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "REJECTED")} disabled={actionLoading} className="text-[#ac120c] border border-[#ac120c] hover:bg-[#ac120c] hover:text-[#f4ede4]">Reject</Button>
                    </>
                  )}
                  
                  {(app.status === "SHORTLISTED" || app.status === "FURTHER_ROUND") && (
                    <>
                      <Button variant="primary" onClick={() => router.push(`/admin/interviews?scheduleFor=${candidate.id}`)} disabled={actionLoading}>Schedule Interview</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "REJECTED")} disabled={actionLoading} className="text-[#ac120c] border border-[#ac120c] hover:bg-[#ac120c] hover:text-[#f4ede4]">Reject</Button>
                    </>
                  )}
                  
                  {(app.status === "INTERVIEW_COMPLETED" || app.status === "WAITLISTED") && (
                    <>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "SELECTED")} disabled={actionLoading} className="text-[#2ecc71] border border-[#2ecc71] hover:bg-[#2ecc71] hover:text-[#0a0202]">Select</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "WAITLISTED")} disabled={actionLoading} className="text-[#f1c40f] border border-[#f1c40f] hover:bg-[#f1c40f] hover:text-[#0a0202]">Waitlist</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "FURTHER_ROUND")} disabled={actionLoading} className="text-[#3498db] border border-[#3498db] hover:bg-[#3498db] hover:text-[#0a0202]">Further Round</Button>
                      <Button variant="ghost" onClick={() => updateApplicationStatus(app.id, "REJECTED")} disabled={actionLoading} className="text-[#ac120c] border border-[#ac120c] hover:bg-[#ac120c] hover:text-[#f4ede4]">Reject</Button>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>

      <Card className="p-6">
        <h2 className="text-[#d07d22] font-mono text-[14px] uppercase mb-4">Interview History</h2>
        {candidate.interviews?.length === 0 ? (
          <p className="text-[#bfa8a2] font-mono">No interviews scheduled.</p>
        ) : (
          <div className="flex flex-col gap-6">
            {candidate.interviews?.map((interview: any, i: number) => (
              <div key={interview.id} className="bg-[#1a0606] p-4 rounded border border-[#2a0d0d] flex flex-col gap-4">
                <div className="flex justify-between border-b border-[#2a0d0d] pb-2">
                  <h3 className="text-[#f4ede4] font-medium">Round {i + 1} - {new Date(interview.date).toLocaleDateString('en-US', { timeZone: 'Asia/Kolkata' })}</h3>
                  <StatusPill status={interview.status === 'COMPLETED' ? 'selected' : 'pending'}>{interview.status}</StatusPill>
                </div>
                
                <div className="flex flex-col gap-2">
                  <p className="text-[#bfa8a2] text-sm">Time: {new Date(interview.start_time).toLocaleTimeString('en-US', { timeZone: 'Asia/Kolkata' })} - {new Date(interview.end_time).toLocaleTimeString('en-US', { timeZone: 'Asia/Kolkata' })}</p>
                  {interview.meeting_link && (
                    <a href={interview.meeting_link} target="_blank" rel="noreferrer" className="text-[#d07d22] text-sm underline">Join Meeting</a>
                  )}
                </div>

                {interview.feedback && interview.feedback.length > 0 && (
                  <div className="mt-2">
                    <h4 className="text-[#d07d22] font-mono text-[12px] uppercase mb-2">Feedback</h4>
                    {interview.feedback.map((fb: any) => (
                      <div key={fb.id} className="bg-[#2a0d0d]/30 p-3 rounded mb-2 text-sm text-[#f4ede4]">
                        <p><span className="text-[#bfa8a2]">Score:</span> {fb.overall_score} / 25</p>
                        <p><span className="text-[#bfa8a2]">Recommendation:</span> {fb.recommendation}</p>
                        <p className="mt-1 text-[#bfa8a2] italic">"{fb.comments}"</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { useParams, useRouter } from "next/navigation"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { Modal } from "@/components/ui/Modal"

export default function FormDetailsPage() {
  const params = useParams()
  const router = useRouter()
  const [form, setForm] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [isQuestionModalOpen, setIsQuestionModalOpen] = useState(false)
  
  const [qData, setQData] = useState({
    question: "",
    type: "TEXT",
    required: true,
    options: ""
  })

  useEffect(() => {
    fetchForm()
  }, [])

  const fetchForm = async () => {
    try {
      const res = await fetchApi(`/api/forms/${params.id}`)
      if (!res.ok) {
        router.push("/admin/forms")
        return
      }
      const data = await res.json()
      setForm(data.form)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleAddQuestion = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      const optionsArray = qData.options.split(",").map(s => s.trim()).filter(Boolean)
      
      await fetchApi(`/api/forms/${params.id}/questions`, {  
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          question: qData.question,
          type: qData.type,
          required: qData.required,
          options: (qData.type === 'RADIO' || qData.type === 'DROPDOWN' || qData.type === 'CHECKBOX') ? optionsArray : []
        })
      })
      setIsQuestionModalOpen(false)
      setQData({ question: "", type: "TEXT", required: true, options: "" })
      fetchForm()
    } catch (err) {
      console.error(err)
    }
  }

  const handleDeleteQuestion = async (qId: number) => {
    if (!confirm("Delete this question?")) return
    try {
      await fetchApi(`/api/forms/${params.id}/questions/${qId}`, {  
        method: "DELETE"
      })
      fetchForm()
    } catch (err) {
      console.error(err)
    }
  }

  if (loading) return <div className="p-8 text-[#bfa8a2] font-mono">LOADING FORM...</div>
  if (!form) return <div className="p-8 text-[#ac120c] font-mono">FORM NOT FOUND</div>

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <header className="flex items-end justify-between">
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
            <DiamondIcon />
            <span>Form Builder</span>
          </div>
          <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
            {form.title}
          </h1>
          <p className="text-[#bfa8a2] font-mono mt-1">{form.description}</p>
        </div>
        <div className="flex gap-4">
          <Button variant="ghost" onClick={() => router.push("/admin/forms")}>BACK TO FORMS</Button>
          {form.status === "DRAFT" && (
            <Button variant="cta" onClick={() => setIsQuestionModalOpen(true)}>ADD QUESTION</Button>
          )}
        </div>
      </header>

      <Card className="p-0 overflow-hidden">
        <div className="p-6 border-b border-[#2a0d0d] flex justify-between items-center">
          <h2 className="font-mono text-[#f4ede4] text-[14px]">Questions ({form.questions?.length || 0})</h2>
          <StatusPill status={form.status === 'PUBLISHED' ? 'active' : form.status === 'CLOSED' ? 'rejected' : 'pending'}>
            {form.status}
          </StatusPill>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2]">QUESTION</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2]">TYPE</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2]">REQUIRED</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2]">OPTIONS</th>
                {form.status === "DRAFT" && <th className="p-4 font-mono text-[12px] text-[#bfa8a2]">ACTIONS</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-[#2a0d0d]">
              {(!form.questions || form.questions.length === 0) ? (
                <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">NO QUESTIONS ADDED.</td></tr>
              ) : (
                form.questions.map((q: any) => (
                  <tr key={q.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                    <td className="p-4 text-[#f4ede4] font-medium">{q.question}</td>
                    <td className="p-4 text-[#d07d22] font-mono text-[11px] font-bold">{q.type}</td>
                    <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">{q.required ? "YES" : "NO"}</td>
                    <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">{q.options?.join(", ") || "-"}</td>
                    {form.status === "DRAFT" && (
                      <td className="p-4">
                        <Button variant="ghost" className="py-2 px-4 text-xs text-[#ac120c]" onClick={() => handleDeleteQuestion(q.id)}>DELETE</Button>
                      </td>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      <Modal isOpen={isQuestionModalOpen} onClose={() => setIsQuestionModalOpen(false)}>
        <h2 className="font-display font-bold text-[24px] text-[#f4ede4] mb-6">Add Question</h2>
        <form onSubmit={handleAddQuestion} className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Question Text</label>
            <Input 
              value={qData.question}
              onChange={e => setQData({ ...qData, question: e.target.value })}
              required
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Type</label>
            <select
              value={qData.type}
              onChange={e => setQData({ ...qData, type: e.target.value })}
              className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 focus:outline-none focus:border-[#d07d22] font-mono text-sm"
            >
              <option value="TEXT">Short Text</option>
              <option value="PARAGRAPH">Paragraph</option>
              <option value="RADIO">Radio (Single Choice)</option>
              <option value="DROPDOWN">Dropdown</option>
              <option value="CHECKBOX">Checkbox (Multiple Choice)</option>
            </select>
          </div>
          {(qData.type === 'RADIO' || qData.type === 'DROPDOWN' || qData.type === 'CHECKBOX') && (
            <div className="flex flex-col gap-2">
              <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Options (Comma separated)</label>
              <Input 
                value={qData.options}
                onChange={e => setQData({ ...qData, options: e.target.value })}
                required
                placeholder="Option 1, Option 2, Option 3"
              />
            </div>
          )}
          <div className="flex items-center gap-2 mt-2">
            <input 
              type="checkbox" 
              checked={qData.required} 
              onChange={e => setQData({ ...qData, required: e.target.checked })}
              id="req"
            />
            <label htmlFor="req" className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Required Field</label>
          </div>
          <div className="mt-4 flex justify-end gap-3">
            <Button type="button" variant="ghost" onClick={() => setIsQuestionModalOpen(false)}>CANCEL</Button>
            <Button type="submit" variant="primary">ADD QUESTION</Button>
          </div>
        </form>
      </Modal>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { Modal } from "@/components/ui/Modal"

export default function FormsPage() {
  const [forms, setForms] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [isModalOpen, setIsModalOpen] = useState(false)
  
  const [formData, setFormData] = useState({ 
    title: "", 
    description: "" 
  })

  useEffect(() => {
    fetchForms()
  }, [])

  const fetchForms = async () => {
    try {
      const res = await fetchApi(`/api/forms`)
      const data = await res.json()
      setForms(data.forms || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      await fetchApi(`/api/forms`, {  
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      })
      setIsModalOpen(false)
      fetchForms()
    } catch (err) {
      console.error(err)
    }
  }

  const handleStatusChange = async (id: number, status: string) => {
    try {
      await fetchApi(`/api/forms/${id}`, {  
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status })
      })
      fetchForms()
    } catch (err) {
      console.error(err)
    }
  }

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <header className="flex items-end justify-between">
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
            <DiamondIcon />
            <span>Form Builder</span>
          </div>
          <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
            Recruitment Forms
          </h1>
        </div>
        <Button variant="cta" onClick={() => setIsModalOpen(true)}>CREATE FORM</Button>
      </header>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">ID</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">TITLE</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">STATUS</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">QUESTIONS</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">ACTIONS</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#2a0d0d]">
              {loading ? (
                <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">LOADING FORMS...</td></tr>
              ) : forms.length === 0 ? (
                <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">NO FORMS CONFIGURED.</td></tr>
              ) : (
                forms.map(f => (
                  <tr key={f.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                    <td className="p-4 text-[#d07d22] font-mono text-[13px] font-bold">{f.id}</td>
                    <td className="p-4">
                      <p className="text-[#f4ede4] font-medium">{f.title}</p>
                      <p className="text-[#bfa8a2] font-mono text-[11px] mt-1">{f.description}</p>
                    </td>
                    <td className="p-4">
                      <StatusPill status={f.status === 'PUBLISHED' ? 'active' : f.status === 'CLOSED' ? 'rejected' : 'pending'}>{f.status}</StatusPill>
                    </td>
                    <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">
                      {f.questions?.length || 0} Questions
                    </td>
                    <td className="p-4 flex gap-2">
                      <Button variant="ghost" className="py-2 px-4 text-xs" onClick={() => window.location.href=`/admin/forms/${f.id}`}>MANAGE</Button>
                      {f.status === "DRAFT" && (
                        <Button variant="ghost" className="py-2 px-4 text-xs text-[#2e7d32]" onClick={() => handleStatusChange(f.id, "PUBLISHED")}>PUBLISH</Button>
                      )}
                      {f.status === "PUBLISHED" && (
                        <Button variant="ghost" className="py-2 px-4 text-xs text-[#ac120c]" onClick={() => handleStatusChange(f.id, "CLOSED")}>CLOSE</Button>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}>
        <h2 className="font-display font-bold text-[24px] text-[#f4ede4] mb-6">Create New Form</h2>
        <form onSubmit={handleCreate} className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Form Title</label>
            <Input 
              value={formData.title}
              onChange={e => setFormData({ ...formData, title: e.target.value })}
              required
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Description</label>
            <Input 
              value={formData.description}
              onChange={e => setFormData({ ...formData, description: e.target.value })}
            />
          </div>
          <div className="mt-4 flex justify-end gap-3">
            <Button type="button" variant="ghost" onClick={() => setIsModalOpen(false)}>CANCEL</Button>
            <Button type="submit" variant="primary">CREATE FORM</Button>
          </div>
        </form>
      </Modal>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"

import React, { useState, useEffect } from "react"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { Modal } from "@/components/ui/Modal"
import Link from "next/link"

export default function AdminInterviewsPage() {
  const [interviews, setInterviews] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  // Reschedule Modal State
  const [rescheduleData, setRescheduleData] = useState<{ id: number, panel_id: number, date: string, start_time: string } | null>(null)
  const [rescheduleError, setRescheduleError] = useState("")
  const [rescheduling, setRescheduling] = useState(false)

  useEffect(() => {
    fetchInterviews()
  }, [])

  const fetchInterviews = async () => {
    try {
      const res = await fetchApi(`/api/interviews`)
      const data = await res.json()
      setInterviews(data.interviews || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const formatTime = (dateStr: string) => {
    return new Date(dateStr).toLocaleTimeString("en-US", { timeZone: "Asia/Kolkata", 
      hour: "2-digit", minute: "2-digit"
    })
  }

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString("en-US", { timeZone: "Asia/Kolkata", 
      month: "short", day: "numeric", year: "numeric"
    })
  }

  const handleReschedule = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!rescheduleData) return
    setRescheduling(true)
    setRescheduleError("")

    try {
      const res = await fetchApi(`/api/interviews/${rescheduleData.id}`, {  
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          date: rescheduleData.date,
          start_time: rescheduleData.start_time
        })
      })
      
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || "Rescheduling failed")
      
      setRescheduleData(null)
      fetchInterviews()
    } catch (err: any) {
      setRescheduleError(err.message)
    } finally {
      setRescheduling(false)
    }
  }

  const generateSlots = () => {
    const slots = []
    for (let h = 10; h <= 17; h++) {
      for (let m = 0; m < 60; m += 10) {
        slots.push(`${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`)
      }
    }
    return slots
  }

  const allSlots = generateSlots()

  const getOccupiedSlots = () => {
    if (!rescheduleData || !rescheduleData.date) return new Set()
    
    const occupied = new Set()
    interviews.forEach(inv => {
      // Don't block the slot of the interview being rescheduled
      if (inv.id === rescheduleData.id) return
      
      if (inv.panel_id === rescheduleData.panel_id) {
        const invDate = new Date(inv.date).toISOString().split('T')[0]
        if (invDate === rescheduleData.date) {
          const invTime = new Date(inv.start_time).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' })
          occupied.add(invTime)
        }
      }
    })
    return occupied
  }

  const occupiedSlots = getOccupiedSlots()

  const handleCancel = async (id: number) => {
    if (!confirm("Are you sure you want to cancel this interview?")) return
    try {
      await fetchApi(`/api/interviews/${id}`, {  
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "CANCELLED" })
      })
      fetchInterviews()
    } catch (err) {
      console.error(err)
    }
  }

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out] pb-10">
      <header className="flex items-end justify-between">
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
            <DiamondIcon />
            <span>Global Data View</span>
          </div>
          <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
            All Interviews
          </h1>
        </div>
        <Link href="/admin/interviews/schedule">
          <Button variant="cta">SCHEDULE</Button>
        </Link>
      </header>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[900px]">
            <thead>
              <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">DATE & TIME</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">CANDIDATE</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">PANEL</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">STATUS</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">MEETING</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em] text-right">ACTIONS</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#2a0d0d]">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-[#bfa8a2] font-mono">LOADING DATA...</td></tr>
              ) : interviews.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-[#bfa8a2] font-mono">NO INTERVIEWS FOUND.</td></tr>
              ) : (
                interviews.map((interview) => (
                  <tr key={interview.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                    <td className="p-4">
                      <p className="text-[#f4ede4] font-medium">{formatDate(interview.date)}</p>
                      <p className="text-[#bfa8a2] font-mono text-[11px] mt-1">
                        {formatTime(interview.start_time)} - {formatTime(interview.end_time)}
                      </p>
                    </td>
                    <td className="p-4">
                      <p className="text-[#f4ede4] font-medium">{interview.candidate?.name}</p>
                      <p className="text-[#bfa8a2] font-mono text-[11px] mt-1">{interview.candidate?.department}</p>
                    </td>
                    <td className="p-4 text-[#f4ede4] font-medium">
                      {interview.panel?.name}
                    </td>
                    <td className="p-4">
                      <StatusPill status={interview.status.toLowerCase().includes('cancel') ? 'rejected' : interview.status.toLowerCase().includes('complete') ? 'completed' : 'active'}>
                        {interview.status}
                      </StatusPill>
                    </td>
                    <td className="p-4">
                      {interview.meeting_link ? (
                        <a href={interview.meeting_link} target="_blank" className="text-[#2e7d32] font-medium text-sm hover:underline">
                          JOIN
                        </a>
                      ) : (
                        <span className="text-[#bfa8a2] font-mono text-[11px]">-</span>
                      )}
                    </td>
                    <td className="p-4 text-right flex items-center justify-end gap-2">
                      {interview.status === "SCHEDULED" && (
                        <>
                          <Button 
                            variant="ghost" 
                            className="text-[10px] py-1 px-3"
                            onClick={() => setRescheduleData({ 
                              id: interview.id, 
                              panel_id: interview.panel_id,
                              date: new Date(interview.date).toISOString().split('T')[0],
                              start_time: new Date(interview.start_time).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' }) 
                            })}
                          >
                            RESCHEDULE
                          </Button>
                          <Button 
                            variant="ghost" 
                            className="text-[#ac120c] text-[10px] py-1 px-3"
                            onClick={() => handleCancel(interview.id)}
                          >
                            CANCEL
                          </Button>
                        </>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      <Modal isOpen={!!rescheduleData} onClose={() => setRescheduleData(null)}>
        <h2 className="font-display font-bold text-[24px] text-[#f4ede4] mb-6">Reschedule Interview</h2>
        {rescheduleError && (
          <div className="bg-[#ac120c]/10 border border-[#ac120c]/50 text-[#ac120c] p-3 rounded-lg text-sm font-medium mb-4">
            {rescheduleError}
          </div>
        )}
        <form onSubmit={handleReschedule} className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Date</label>
            <Input 
              type="date"
              value={rescheduleData?.date || ""}
              onChange={(e: any) => setRescheduleData(prev => prev ? { ...prev, date: e.target.value, start_time: "" } : null)}
              required
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Time Slot (10 mins)</label>
            <select
              value={rescheduleData?.start_time || ""}
              onChange={(e: any) => setRescheduleData(prev => prev ? { ...prev, start_time: e.target.value } : null)}
              className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono focus:border-[#d07d22] outline-none"
              required
              disabled={!rescheduleData?.date}
            >
              <option value="" disabled>Select Slot</option>
              {allSlots.map(slot => {
                const isOccupied = occupiedSlots.has(slot)
                return (
                  <option key={slot} value={slot} disabled={isOccupied}>
                    {slot} {isOccupied ? "(Occupied)" : "(Available)"}
                  </option>
                )
              })}
            </select>
          </div>
          <div className="mt-4 flex justify-end gap-3">
            <Button type="button" variant="ghost" onClick={() => setRescheduleData(null)}>CANCEL</Button>
            <Button type="submit" variant="cta" disabled={rescheduling}>
              {rescheduling ? "SAVING..." : "CONFIRM"}
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { Modal } from "@/components/ui/Modal"

export default function PanelsPage() {
  const [panels, setPanels] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [formData, setFormData] = useState<{id?: number, name: string, description: string, status?: string}>({ name: "", description: "" })

  const [users, setUsers] = useState<any[]>([])
  const [selectedUser, setSelectedUser] = useState("")
  const [activePanel, setActivePanel] = useState<number | null>(null)

  useEffect(() => {
    fetchPanels()
    fetchUsers()
  }, [])

  const fetchUsers = async () => {
    try {
      const res = await fetchApi(`/api/users`)
      const data = await res.json()
      setUsers(data.users?.filter((u: any) => u.role === 'PANEL_MEMBER') || [])
    } catch (err) {
      console.error(err)
    }
  }

  const fetchPanels = async () => {
    try {
      const res = await fetchApi(`/api/panels`)
      const data = await res.json()
      setPanels(data.panels || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      const method = formData.id ? "PUT" : "POST"
      await fetchApi(`/api/panels`, {  
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      })
      setIsModalOpen(false)
      fetchPanels()
    } catch (err) {
      console.error(err)
    }
  }

  const handleDelete = async (id: number) => {
    if (!confirm("Are you sure you want to delete this panel?")) return
    try {
      await fetchApi(`/api/panels`, {  
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id })
      })
      fetchPanels()
    } catch (err) {
      console.error(err)
    }
  }

  const handleToggleStatus = async (panel: any) => {
    try {
      const newStatus = panel.status === "ACTIVE" ? "INACTIVE" : "ACTIVE"
      await fetchApi(`/api/panels`, {  
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: panel.id, name: panel.name, description: panel.description, status: newStatus })
      })
      fetchPanels()
    } catch (err) {
      console.error(err)
    }
  }

  const openCreateModal = () => {
    setFormData({ name: "", description: "" })
    setIsModalOpen(true)
  }

  const handleAddMember = async (panel_id: number) => {
    if (!selectedUser) return
    try {
      await fetchApi(`/api/panels/members`, {  
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ panel_id, user_id: selectedUser })
      })
      setSelectedUser("")
      setActivePanel(null)
      fetchPanels()
    } catch (err) {
      console.error(err)
    }
  }

  const handleRemoveMember = async (panel_id: number, user_id: string) => {
    try {
      await fetchApi(`/api/panels/members`, {  
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ panel_id, user_id })
      })
      fetchPanels()
    } catch (err) {
      console.error(err)
    }
  }

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <header className="flex items-end justify-between">
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
            <DiamondIcon />
            <span>Infrastructure Management</span>
          </div>
          <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
            Interview Panels
          </h1>
        </div>
        <Button variant="cta" onClick={openCreateModal}>CREATE PANEL</Button>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          <p className="text-[#bfa8a2] font-mono">LOADING PANELS...</p>
        ) : (
          panels.map(panel => (
            <Card key={panel.id} className="flex flex-col gap-4">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-display font-bold text-[20px] text-[#f4ede4] flex items-center gap-2">
                    {panel.name}
                    <button 
                      onClick={() => { setFormData({ id: panel.id, name: panel.name, description: panel.description, status: panel.status }); setIsModalOpen(true); }}
                      className="text-[#d07d22] hover:text-[#f4ede4] transition-colors"
                      title="Edit Panel"
                    >
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z"></path></svg>
                    </button>
                    <button 
                      onClick={() => handleDelete(panel.id)}
                      className="text-[#ac120c] hover:text-[#f4ede4] transition-colors"
                      title="Delete Panel"
                    >
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>
                    </button>
                  </h3>
                  <p className="text-[#bfa8a2] text-sm mt-1">{panel.description}</p>
                </div>
                <button onClick={() => handleToggleStatus(panel)} className="hover:opacity-80 transition-opacity">
                  <StatusPill status={panel.status.toLowerCase()}>{panel.status}</StatusPill>
                </button>
              </div>
              <div className="mt-4 pt-4 border-t border-[#2a0d0d]">
                <div className="flex justify-between items-center mb-2">
                  <p className="font-mono text-[#d07d22] text-[10px] tracking-widest">MEMBERS</p>
                  <Button variant="ghost" className="text-[10px] py-1 px-2" onClick={() => setActivePanel(activePanel === panel.id ? null : panel.id)}>
                    + ADD
                  </Button>
                </div>
                
                {activePanel === panel.id && (
                  <div className="flex gap-2 mb-3">
                    <select 
                      className="flex-1 bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-1.5 rounded-[4px] font-mono text-[11px]"
                      value={selectedUser}
                      onChange={(e) => setSelectedUser(e.target.value)}
                    >
                      <option value="">Select Panel Member...</option>
                      {users.map(u => (
                        <option key={u.id} value={u.id}>{u.name}</option>
                      ))}
                    </select>
                    <Button variant="primary" className="py-1.5 px-3 text-[10px]" onClick={() => handleAddMember(panel.id)}>
                      OK
                    </Button>
                  </div>
                )}

                {panel.members?.length === 0 ? (
                  <p className="text-[#bfa8a2] text-xs font-mono">NO MEMBERS ASSIGNED</p>
                ) : (
                  <ul className="text-[#f4ede4] text-sm font-medium flex flex-col gap-2">
                    {panel.members?.map((m: any) => (
                      <li key={m.id} className="flex justify-between items-center group">
                        <span>- {m.user.name}</span>
                        <button 
                          onClick={() => handleRemoveMember(panel.id, m.user_id)}
                          className="text-[#ac120c] font-mono text-[10px] opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                          REMOVE
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </Card>
          ))
        )}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}>
        <h2 className="font-display font-bold text-[24px] text-[#f4ede4] mb-6">Create New Panel</h2>
        <form onSubmit={handleCreate} className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Panel Name</label>
            <Input 
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
              required
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Description</label>
            <Input 
              value={formData.description}
              onChange={e => setFormData({ ...formData, description: e.target.value })}
            />
          </div>
          <div className="mt-4 flex justify-end gap-3">
            <Button type="button" variant="ghost" onClick={() => setIsModalOpen(false)}>CANCEL</Button>
            <Button type="submit" variant="primary">CREATE</Button>
          </div>
        </form>
      </Modal>
    </div>
  )
}

"use client"
import { fetchApi } from "@/api-client"


import React, { useState, useEffect } from "react"
import { Card } from "@/components/ui/Card"
import { DiamondIcon } from "@/components/ui/Icons"
import { StatusPill } from "@/components/ui/StatusPill"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { Modal } from "@/components/ui/Modal"

export default function UsersPage() {
  const [users, setUsers] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [isModalOpen, setIsModalOpen] = useState(false)
    const [formData, setFormData] = useState({ 
    id: "",
    name: "", 
    email: "", 
    password: "",
    role: "PANEL_MEMBER",
    departments: "CSE",
    active: true
  })

  useEffect(() => {
    fetchUsers()
  }, [])

  const fetchUsers = async () => {
    try {
      const res = await fetchApi(`/api/users`)
      const data = await res.json()
      setUsers(data.users || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      const payload = {
        ...formData,
        departments: formData.departments.split(',').map(d => d.trim()),
        active: formData.active
      }
      const method = formData.id ? "PUT" : "POST"
      await fetchApi(`/api/users`, {  
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      })
      setIsModalOpen(false)
      fetchUsers()
    } catch (err) {
      console.error(err)
    }
  }

  const openCreateModal = () => {
    setFormData({ id: "", name: "", email: "", password: "", role: "PANEL_MEMBER", departments: "CSE", active: true })
    setIsModalOpen(true)
  }

  return (
    <div className="flex flex-col gap-8 animate-[fadeIn_0.5s_ease-out]">
      <header className="flex items-end justify-between">
        <div className="flex flex-col gap-2">
          <div className="flex items-center gap-3 text-[#d07d22] font-mono text-[11.5px] uppercase tracking-[0.2em]">
            <DiamondIcon />
            <span>Access Control</span>
          </div>
          <h1 className="font-display font-bold text-[32px] sm:text-[40px] leading-tight text-[#f4ede4]">
            User Management
          </h1>
        </div>
        <Button variant="cta" onClick={openCreateModal}>CREATE USER</Button>
      </header>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[600px]">
            <thead>
              <tr className="bg-[#370b09]/50 border-b border-[#2a0d0d]">
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">NAME</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">ROLE</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">DEPARTMENTS</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em]">STATUS</th>
                <th className="p-4 font-mono text-[12px] text-[#bfa8a2] font-normal tracking-[0.06em] text-right">ACTIONS</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#2a0d0d]">
              {loading ? (
                <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">LOADING USERS...</td></tr>
              ) : users.length === 0 ? (
                <tr><td colSpan={5} className="p-8 text-center text-[#bfa8a2] font-mono">NO USERS FOUND.</td></tr>
              ) : (
                users.map(user => (
                  <tr key={user.id} className="hover:bg-[#1a0606] transition-colors duration-200">
                    <td className="p-4">
                      <p className="text-[#f4ede4] font-medium">{user.name}</p>
                      <p className="text-[#bfa8a2] font-mono text-[11px] mt-1">{user.email}</p>
                    </td>
                    <td className="p-4">
                      <StatusPill status={user.role === 'ADMIN' ? 'active' : 'pending'}>{user.role}</StatusPill>
                    </td>
                    <td className="p-4 text-[#bfa8a2] font-mono text-[11px]">
                      {user.departments?.join(", ") || "-"}
                    </td>
                    <td className="p-4">
                      {user.active ? (
                        <span className="text-[#2e7d32] font-mono text-[11px]">ACTIVE</span>
                      ) : (
                        <span className="text-[#ac120c] font-mono text-[11px]">DISABLED</span>
                      )}
                    </td>
                    <td className="p-4 text-right space-x-2">
                      <button 
                        onClick={() => {
                          setFormData({ 
                            id: user.id,
                            name: user.name, 
                            email: user.email, 
                            password: "",
                            role: user.role, 
                            departments: user.departments?.join(', ') || '',
                            active: user.active
                          })
                          setIsModalOpen(true)
                        }}
                        className="text-[#d07d22] font-mono text-[10px] uppercase hover:underline"
                      >
                        EDIT
                      </button>
                      <button 
                        onClick={async () => {
                          if (confirm("Are you sure you want to delete this user?")) {
                            await fetchApi(`/api/users`, {   method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: user.id }) })
                            fetchUsers()
                          }
                        }}
                        className="text-[#ac120c] font-mono text-[10px] uppercase hover:underline ml-2"
                      >
                        DELETE
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}>
        <h2 className="font-display font-bold text-[24px] text-[#f4ede4] mb-6">Provision User</h2>
        <form onSubmit={handleCreate} className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Full Name</label>
            <Input 
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
              required
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Email Address</label>
            <Input 
              type="email"
              value={formData.email}
              onChange={e => setFormData({ ...formData, email: e.target.value })}
              required
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Temporary Password</label>
            <Input 
              type="password"
              value={formData.password}
              onChange={e => setFormData({ ...formData, password: e.target.value })}
            />
          </div>
          <div className="flex flex-col gap-2">
            <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">System Role</label>
            <select
              value={formData.role}
              onChange={(e) => setFormData({ ...formData, role: e.target.value })}
              className="w-full bg-[#120202] border border-[#2a0d0d] text-[#f4ede4] p-3 rounded-[8px] font-mono focus:border-[#d07d22] outline-none"
            >
              <option value="PANEL_MEMBER">PANEL MEMBER</option>
              <option value="RECRUITER">RECRUITER</option>
              <option value="ADMIN">ADMINISTRATOR</option>
            </select>
          </div>
          {formData.role === "RECRUITER" && (
            <div className="flex flex-col gap-2">
              <label className="font-mono text-[11px] text-[#bfa8a2] uppercase tracking-widest">Departments (Comma separated)</label>
              <Input 
                value={formData.departments}
                onChange={e => setFormData({ ...formData, departments: e.target.value })}
                placeholder="CSE, ECE"
              />
            </div>
          )}
          <div className="flex items-center gap-2 mt-2">
            <input
              type="checkbox"
              id="active"
              checked={formData.active}
              onChange={(e) => setFormData({ ...formData, active: e.target.checked })}
              className="appearance-none w-4 h-4 border border-[#d07d22] checked:bg-[#ac120c] transition-all rounded-sm cursor-pointer"
            />
            <label htmlFor="active" className="font-mono text-[12px] text-[#bfa8a2] uppercase tracking-widest cursor-pointer">
              Active User Account
            </label>
          </div>
          <div className="mt-4 flex justify-end gap-3">
            <Button type="button" variant="ghost" onClick={() => setIsModalOpen(false)}>CANCEL</Button>
            <Button type="submit" variant="primary">SAVE</Button>
          </div>
        </form>
      </Modal>
    </div>
  )
}

